module.exports = /*#__PURE__*/JSON.parse('{"navbar":{"brand":"Afkanerd","home":"Home","about":"About","projects":"Projects","careers":"Careers","blog":"Blog","contact":"Get in Touch","language":"Language","language.en":"English","language.fr":"French","language.fa":"Farsi"},"hero":{"title":"AFKANERD","subtitle1":"We are a team of developers, researchers, and nerds building open source software for digital rights, security, and privacy. Our work spans secure messaging, cryptography, decentralized communication, healthcare, and more.","subtitle2":"We also collaborate with open source projects and individuals. If you\'re building something that benefits the open source community, we\'d be glad to help. Reach out."},"about":{"title":"./About","quote":"Source/Los Alamos: ENIAC, the world\'s first digital computer, unveiled 70 years ago Sunday at the University of Pennsylvania, had six primary programmers: Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Wescoff, Fran Bilas and Ruth Lichterman. They were initially called \\"operators.\\" - phillyvoice.com","description":"We are inspired by many great individuals who take action. We know we can only inspire change and drive development by leading the way. We build in the open and encourage you to join us on our mission to make the world more open and more accessible to all."},"project":{"title":"./Projects"},"project1":{"title":"SMSWithoutBorders","description":"{ SMSWithoutBorders is dedicated to researching, developing and promoting secure and accessible communication tools that function even without an internet connection. Some  of SMSWithoutBorders projects include RelaySMS and DekuSMS. We also have white papers and research papers on secure communication and privacy-first infrastructure.}","readMore":"Website"},"project2":{"title":"DekuSMS","description":"DekuSMS is an Android SMS messaging app. It enables 2 users of the app to communicate using end-to-end encryption over SMS messages. The app also contains message forwarding abilities supporting protocols such as SMTP, FTP, and AMQP. The app is built to integrate with RabbitMQ allowing users with messaging queues to set up and make remote communication requests to their apps.","readMore":"Website"},"blog":{"title":"./Blog/latest"},"blog1":{"title":"New Alpha Release: Vault 0.1.0","description":"SMSWithoutBorders Vault 0.1.0 is Now Available in Alpha Release! The Vault is a technology developed by the SMSWithoutBorders team to secure users\' access tokens and facilitate the secure usage of these tokens for publishing users\' messages.","readMore":"Read More"},"blog2":{"title":"Rebranding","description":"SMSWithoutBorders itself is becoming the umbrella project encompassing RelaySMS and other messaging tools. The core functionality remains the same, but users can expect a new name, enhanced security features, and a focus on future growth under the SMSWithoutBorders project.","readMore":"Read More"},"footer":{"title":"AFKANERD LABS","title1":"Follow Us","Policy":"Privacy Policy","blog":"Blog","Project":"Projects","copyright":"copyright © 2024 AFKANERD LABS."}}');

