module.exports = /*#__PURE__*/JSON.parse('{"navbar":{"brand":"Afkanerd","home":"خانه","about":"درباره ما","projects":"پروژه‌ها","jobs":"موقعیت‌های شغلی","blog":"بلاگ","contact":"تماس با ما","language":"زبان","language.en":"انگلیسی","language.fr":"فرانسوی","language.fa":"فارسی"},"hero":{"title":"AFKANERD","subtitle1":"ما به صورت منبع‌باز و شفاف توسعه می‌دهیم. فناوری‌هایی برای حقوق دیجیتال، امنیت و حریم خصوصی می‌سازیم. ابزارهای ما به صورت آزاد برای فعالیت‌های حقوقی، درمانی و آموزشی در دسترس هستند.","subtitle2":"همچنین با پروژه‌های منبع‌باز و افراد مشاوره می‌دهیم. اگر پروژه شما به جامعه منبع‌باز خدمت می‌کند، با کمال میل مشاوره خواهیم داد - با ما در تماس باشید."},"about":{"title":"./AFKANERD","quote":"منبع/لس آلاموس: ENIAC، اولین کامپیوتر دیجیتال جهان، ۷۰ سال پیش در دانشگاه پنسیلوانیا رونمایی شد و شش برنامه‌نویس اصلی آن: کی مک‌نالتی، بتی جنینگز، بتی اسنایدر، مارلین وسکاف، فران بیلاس و روت لیخترمن بودند. در ابتدا به آنها \'اپراتور\' گفته می‌شد. - phillyvoice.com","description":"ما از افراد بزرگی که اقدام می‌کنند الهام می‌گیریم. می‌دانیم که تنها با هدایت می‌توانیم تغییر ایجاد کنیم و توسعه را پیش ببریم. ما به صورت شفاف کار می‌کنیم و شما را تشویق می‌کنیم که در مأموریت ما برای دنیایی بازتر و در دسترس‌تر برای همه، به ما بپیوندید."},"project":{"title":"./پروژه‌ها"},"project1":{"title":"SMSWithoutBorders","description":"SMSWithoutBorders به تحقیق، توسعه و ترویج ابزارهای ارتباطی امن و در دسترس اختصاص دارد که حتی بدون اتصال به اینترنت کار می‌کنند. توسعه شامل برنامه‌های موبایلی برای پلتفرم‌های مختلف مانند اندروید، iOS و سیستم‌های لینوکسی است. برخی از کارها همچنین شامل مقالات سفید در مورد موضوعاتی مانند رمزنگاری، ارتباطات و آزادی اینترنت است.","readMore":"مطالعه بیشتر"},"project2":{"title":"DekuSMS","description":"DekuSMS یک برنامه پیام‌رسان SMS برای اندروید است. این برنامه به دو کاربر اجازه می‌دهد تا از طریق پیام‌های SMS با رمزگذاری انتها به انتها ارتباط برقرار کنند. همچنین قابلیت انتقال پیام‌ها را با پشتیبانی از پروتکل‌هایی مانند SMTP، FTP و AMQP دارد. این برنامه برای ادغام با RabbitMQ طراحی شده است و به کاربران امکان می‌دهد تا صف‌های پیام‌رسانی راه‌اندازی کنند و درخواست‌های ارتباطی از راه دور را به برنامه‌های خود ارسال کنند.","readMore":"مطالعه بیشتر"},"blog":{"title":"./بلاگ/آخرین"},"blog1":{"title":"انتشار نسخه آلفا: Vault 0.1.0","description":"نسخه آلفا SMSWithoutBorders Vault 0.1.0 اکنون در دسترس است! Vault یک فناوری است که توسط تیم SMSWithoutBorders برای امنیت نشانه‌های دسترسی کاربران و تسهیل استفاده امن از این نشانه‌ها برای انتشار پیام‌های کاربران توسعه داده شده است.","readMore":"مطالعه بیشتر"},"blog2":{"title":"تغییر نام تجاری","description":"SMSWithoutBorders اکنون به پروژه اصلی تبدیل شده که شامل RelaySMS و دیگر ابزارهای پیام‌رسانی است. قابلیت‌های اصلی همچنان همان باقی می‌مانند، اما کاربران می‌توانند انتظار نام جدید، ویژگی‌های امنیتی بهبود یافته و تمرکز بر رشد آینده تحت پروژه SMSWithoutBorders را داشته باشند.","readMore":"مطالعه بیشتر"},"footer":{"title":"AFKANERD INFOTECH","title1":"ما را دنبال کنید","Policy":"سیاست حفظ حریم خصوصی","blog":"بلاگ","Project":"پروژه‌ها"}}');

